    EnTextos.textMsjModoDepresiometro,
    'Otomatik: Pencerelerin pozisyonu negatif basınca göre otomatik olarak hesaplanacaktır./nManuel: Havalandırma kademelerinde negatif basınçla kontrol edilen girişlerin açılışını belirtmemiz gerekmektedir.'
